package com.valentinebsaa.rotatemuse;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.view.*;
import android.widget.*;
import android.hardware.*;
import android.media.*;
import java.io.*;
import java.util.*;

@androidx.media3.common.util.UnstableApi
public class MainActivity extends Activity {
 Prefs prefs; LinearLayout page,body; String tab="Display"; TextView message;
 final int ink=0xffeee9f4,muted=0xffb1a8c1,accent=0xffd8b98d;
 int dp(int x){return (int)(getResources().getDisplayMetrics().density*x+.5f);}
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=new Prefs(this);if(state!=null)tab=state.getString("tab","Display");show(tab);}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("tab",tab);}
 TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(7));return v;}
 void note(String s){body.addView(text(s,14,muted));}
 GradientDrawable panel(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));d.setStroke(dp(1),0xff41354e);return d;}
 Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(ink);b.setBackground(panel(0xff2a2238));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(49));lp.setMargins(0,dp(5),0,dp(5));body.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 void show(String name){tab=name;page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(0xff100e19);page.setPadding(dp(18),dp(12),dp(18),0);setContentView(page);
  TextView title=text("Rotate Muse",29,ink);title.setTypeface(Typeface.create("serif",Typeface.NORMAL));page.addView(title);
  HorizontalScrollView nav=new HorizontalScrollView(this);nav.setHorizontalScrollBarEnabled(false);LinearLayout links=new LinearLayout(this);for(String n:new String[]{"Display","Themes","My Videos","Clock","Automation","Settings"}){TextView link=text(n,14,n.equals(name)?accent:muted);link.setPadding(dp(10),dp(7),dp(10),dp(12));link.setFocusable(true);link.setOnClickListener(v->show(n));links.addView(link);}nav.addView(links);page.addView(nav);
  ScrollView scroll=new ScrollView(this);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,0,0,dp(20));scroll.addView(body);
  switch(name){case "Display":displayPage();break;case "Themes":themes();break;case "My Videos":videos();break;case "Clock":clock();break;case "Automation":automation();break;default:settings();}
 }
 void preview(){boolean celestial=prefs.s("theme","neon").equals("celestial");FrameLayout card=new FrameLayout(this);card.setBackground(panel(0xff201a2b));card.setClipToOutline(true);card.addView(new ThemeView(this,celestial,false),new FrameLayout.LayoutParams(-1,-1));TextView label=text(prefs.s("media","").isEmpty()?(celestial?"Celestial Dream":"Neon Nostalgia"):"Your imported animation",18,ink);label.setPadding(dp(14),dp(8),dp(14),dp(8));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);card.addView(label,lp);body.addView(card,new LinearLayout.LayoutParams(-1,dp(175)));}
 void launch(){startActivity(new Intent(this,DisplayActivity.class));}
 void displayPage(){preview();button("Enter display",this::launch);note("Quiet motion. Your clock. Your space.");note("Manual beta · Back or the Exit button returns here. Swivel automation awaits a physical hardware test.");}
 void themes(){note("Original procedural demos · import a cinematic video for a finished character animation.");for(String id:new String[]{"neon","celestial"}){boolean c=id.equals("celestial");body.addView(new ThemeView(this,c,false),new LinearLayout.LayoutParams(-1,dp(135)));button((c?"Celestial Dream":"Neon Nostalgia")+(prefs.s("theme","neon").equals(id)?" · selected":""),()->{prefs.set("theme",id);prefs.set("media","");show("Themes");});}button("Preview selected theme",this::launch);}
 void videos(){note("Choose a local MP4 or GIF. Import makes a private copy (up to 512 MiB); your original stays untouched.");button("Import video or GIF",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/mp4","image/gif"});i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);});
  message=text("",14,accent);body.addView(message);File[] files=new File(getFilesDir(),"media").listFiles();if(files==null||files.length==0)note("Your video shelf is empty.");else for(File f:files){if(f.getName().endsWith(".part"))continue;Button item=button((prefs.s("media","").equals(f.getName())?"Selected · ":"")+prefs.s("label:"+f.getName(),f.getName()),()->{prefs.set("media",f.getName());show("My Videos");});item.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Remove imported copy?").setMessage("Your original media stays untouched.").setNegativeButton("Keep",null).setPositiveButton("Remove",(d,w)->{if(f.delete()){if(prefs.s("media","").equals(f.getName()))prefs.set("media","");show("My Videos");}else toast("Could not remove the private copy.");}).show();return true;});}
  button("Preview selection",this::launch);note("Hold an imported title to remove its private copy. Your original media stays untouched.");}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=20||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String type=getContentResolver().getType(uri);if(!Rules.mediaType(type)){toast("Choose an MP4 video or GIF image.");return;}String displayName="Imported animation";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())displayName=cursor.getString(0);}catch(Exception ignored){}final String importedLabel=displayName;if(message!=null)message.setText("Importing a private copy…");
  new Thread(()->{File dir=new File(getFilesDir(),"media");dir.mkdirs();String id=UUID.randomUUID().toString().substring(0,8)+(type.equals("image/gif")?".gif":".mp4");File tmp=new File(dir,id+".part"),out=new File(dir,id);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream os=new FileOutputStream(tmp)){if(in==null)throw new IOException("The selected file is unavailable.");byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>Rules.MAX_IMPORT)throw new IOException("Import exceeds 512 MiB.");os.write(buffer,0,n);}if(total==0)throw new IOException("The selected file is empty.");os.close();if(!tmp.renameTo(out))throw new IOException("Could not finish import.");prefs.set("media",id);prefs.set("label:"+id,importedLabel);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()){show("My Videos");toast("Imported. Preview to check playback.");}});}catch(Exception e){tmp.delete();runOnUiThread(()->toast("Import failed: "+e.getMessage()));}},"muse-import").start();}
 @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getKeyCode()==KeyEvent.KEYCODE_F9||event.getKeyCode()==KeyEvent.KEYCODE_F12)prefs.set("candidate","Foreground key "+KeyEvent.keyCodeToString(event.getKeyCode())+" action="+event.getAction()+" at "+new Date()+" (not confirmed as swivel)");return super.dispatchKeyEvent(event);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void toggle(String label,String key,boolean def){Switch sw=new Switch(this);sw.setText(label);sw.setTextColor(ink);sw.setPadding(0,dp(9),0,dp(9));sw.setChecked(prefs.b(key,def));sw.setOnCheckedChangeListener((v,b)->prefs.set(key,b));body.addView(sw);}
 void choice(String label,String key,String[] items,int def){body.addView(text(label,15,ink));Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items);s.setAdapter(a);s.setSelection(Math.min(items.length-1,prefs.i(key,def)));s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){prefs.set(key,pos);}public void onNothingSelected(AdapterView<?> p){}});body.addView(s);}
 void clock(){toggle("Show clock","clock",true);toggle("24-hour time","h24",false);toggle("Show seconds","seconds",false);toggle("Show date","date",true);toggle("Soft clock shadow","shadow",true);
  choice("Typeface","font",new String[]{"Refined serif","Clean sans","Monospace"},0);choice("Color","color",new String[]{"Pearl","Champagne","Rose","Ice"},0);choice("Clock position","position",new String[]{"Bottom left","Bottom right","Top left","Top right","Saved drag position"},0);choice("Opacity","opacity",new String[]{"100%","85%","65%","45%"},1);button("Preview and drag the clock",this::launch);}
 void automation(){body.addView(text("Manual mode is ready",23,ink));note("Automatic swivel activation is not confirmed. Motion, screen-off and orientation changes do not prove the swivel is closed.");note("No background service or privileged permission is enabled. Use the app icon, then Enter display. Back returns without launching HOME or terminating another app.");note("To finish research: capture input events while physically closing and opening the screen, compare broadcasts and stock clock behavior, then verify a supported activation path. Android 12 restricts background activity launches.");button("View diagnostics",this::diagnostics);}
 void settings(){choice("Video framing","fit",new String[]{"Fit","Fill (stretch)","Center crop"},0);choice("Dim display after","dim",new String[]{"30 seconds","1 minute","2 minutes","Never"},0);choice("Stop keeping screen awake after","sleep",new String[]{"2 minutes","5 minutes","10 minutes","Never"},1);note("After the timeout, playback ends and Android's own screen timeout takes over. The app cannot force-lock your device. Brightness is changed only for this window.");button("Diagnostics",this::diagnostics);note("Rotate Muse 0.1.0-beta · Offline · No account, telemetry, network, overlay, accessibility or broad storage access.");}
 void diagnostics(){StringBuilder s=new StringBuilder("Device: "+Build.MODEL+"\nAndroid "+Build.VERSION.RELEASE+" / API "+Build.VERSION.SDK_INT+"\nDisplay: "+getResources().getDisplayMetrics().widthPixels+" × "+getResources().getDisplayMetrics().heightPixels+"\nScreen interactive: "+((PowerManager)getSystemService(POWER_SERVICE)).isInteractive()+"\nSelected: "+prefs.s("media",prefs.s("theme","neon"))+"\nPlayback: "+prefs.s("playback","Not started")+"\nLast error: "+prefs.s("error","None")+"\nLast candidate event: "+prefs.s("candidate","None observed in foreground")+"\nSwivel: pending physical validation\nEvent source: none confirmed\nAutomatic activation: disabled\nSpecial permissions: none\n\nAVC decoders:\n");for(MediaCodecInfo i:new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos()){if(i.isEncoder())continue;for(String t:i.getSupportedTypes())if(t.equals("video/avc"))s.append(i.getName()).append(" hardware=").append(i.isHardwareAccelerated()).append('\n');}s.append("\nCandidate sensors (not proof of closure):\n");for(Sensor sensor:((SensorManager)getSystemService(SENSOR_SERVICE)).getSensorList(Sensor.TYPE_ALL))if(sensor.getStringType().contains("hinge")||sensor.getName().toLowerCase(Locale.US).contains("hall"))s.append(sensor.getName()).append('\n');new AlertDialog.Builder(this).setTitle("Device diagnostics").setMessage(s.toString()).setPositiveButton("Done",null).show();}
}
